options.afterRender:
// Four switches for the map's layers: satellite, rain, isobars and wind chance. Each writes its
// variable (on or off); the map's query for that layer then returns its rows
// or none, so a layer switched off costs nothing to load. Built here, not in
// the content: the panel sanitizes its content, and buttons would not survive.
//
// ${satellite} ${rain} ${isobars} ${windchance} are named here so the panel redraws when either changes.

// @constants begin
const SWITCHES = [
  { variable: 'satellite', label: 'Satellite', hint: 'Infrared from GOES or Himawari (NASA GIBS), cloud tops coloured by how cold they are', colour: '#9ad0a0' },
  { variable: 'rain', label: 'Rain', hint: 'Rain measured from space (IMERG) until some six hours ago, then GFS rain over 0.3 mm/h as blue dots', colour: '#5aaaff' },
  { variable: 'isobars', label: 'Isobars', hint: 'GFS sea-level pressure, as lines coloured by their gradient', colour: '#d37d87' },
  { variable: 'windchance', label: 'Wind chance', hint: 'Chance of winds over 34 kt in the next five days, from the latest NHC or JTWC advisory', colour: '#a06ee8' },
];
// @constants end

const root = context.element.querySelector('.layers');
if (!root) {
  return;
}
const value = (name) => context.grafana.replaceVariables('${' + name + '}');
root.innerHTML = '';
for (const s of SWITCHES) {
  const on = value(s.variable) !== 'off';
  const button = document.createElement('button');
  button.className = 'layers-switch' + (on ? ' on' : '');
  button.title = s.hint + (on ? ' (shown: click to hide)' : ' (hidden: click to show)');
  button.style.setProperty('--accent', s.colour);
  button.innerHTML = '<span class="layers-dot"></span>' + s.label;
  button.addEventListener('click', () => {
    context.grafana.locationService.partial({ ['var-' + s.variable]: on ? 'off' : 'on' }, true);
  });
  root.appendChild(button);
}

options.styles:
.layers { display: flex; align-items: center; gap: 8px; height: 100%; flex-wrap: wrap; }
.layers-switch { display: inline-flex; align-items: center; gap: 8px; padding: 4px 14px; border-radius: 999px;
  border: 1px solid var(--accent); background: transparent; color: inherit; font-size: 13px; cursor: pointer;
  opacity: 0.6; }
.layers-switch.on { background: color-mix(in srgb, var(--accent) 22%, transparent); opacity: 1; }
.layers-dot { width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--accent); }
.layers-switch.on .layers-dot { background: var(--accent); }
